import{_ as e}from"./chunks/thumb-03.BeWoiesU.js";import{_ as r}from"./chunks/photo-12.BQJB7tI9.js";import{_ as t,H as o,f as s,i}from"./chunks/framework.Cvt1eIE0.js";const u=JSON.parse('{"title":"收藏｜X 热议的「资深工程师」迷思与反论","description":"","frontmatter":{"title":"收藏｜X 热议的「资深工程师」迷思与反论","date":"2026-05-25T00:00:00.000Z","category":"收藏","tags":["收藏","职业","X"],"excerpt":"整理关于十年经验、面试 LeetCode 与 IC 转管理的社区争论，供职业阶段自省。"},"headers":[],"relativePath":"posts/收藏/x-senior-dev-career-myths.md","filePath":"posts/收藏/x-senior-dev-career-myths.md"}'),n={name:"posts/收藏/x-senior-dev-career-myths.md"};function l(d,a,h,c,p,m){return o(),s("div",null,[...a[0]||(a[0]=[i('<img src="'+e+'" alt="配图" class="article-banner" loading="lazy"><div class="figure wide"><img src="'+r+'" alt="随拍配图" loading="lazy"><p class="figure-caption">光影把抽象话题拽回可触摸的现实。</p></div><h1 id="「资深工程师」迷思收藏" tabindex="-1">「资深工程师」迷思收藏 <a class="header-anchor" href="#「资深工程师」迷思收藏" aria-label="Permalink to &quot;「资深工程师」迷思收藏&quot;">​</a></h1><p>职业类讨论在 X 上极易传播，因触及身份焦虑。以下为常见<strong>迷思—反论</strong>对，便于收藏后冷静阅读。</p><h2 id="迷思-1-十年经验-十年成长" tabindex="-1">迷思 1：十年经验 = 十年成长 <a class="header-anchor" href="#迷思-1-十年经验-十年成长" aria-label="Permalink to &quot;迷思 1：十年经验 = 十年成长&quot;">​</a></h2><p><strong>反论帖</strong>：十年重复第一年经验（「1 year × 10」）。解药是刻意换域：网络、存储、业务、领导力轮换。</p><h2 id="迷思-2-资深-不再写代码" tabindex="-1">迷思 2：资深 = 不再写代码 <a class="header-anchor" href="#迷思-2-资深-不再写代码" aria-label="Permalink to &quot;迷思 2：资深 = 不再写代码&quot;">​</a></h2><p><strong>反论</strong>：Staff/Principal 工程路径要求深技术判断。完全脱离代码易脱离真实摩擦。</p><h2 id="迷思-3-刷题无用论-vs-唯刷题论" tabindex="-1">迷思 3：刷题无用论 vs 唯刷题论 <a class="header-anchor" href="#迷思-3-刷题无用论-vs-唯刷题论" aria-label="Permalink to &quot;迷思 3：刷题无用论 vs 唯刷题论&quot;">​</a></h2><p>两极都火。折中共识：<strong>面试题考的是沟通与问题分解</strong>，算法只是载体；入职后价值在交付与协作。</p><h2 id="迷思-4-必须转管理才涨薪" tabindex="-1">迷思 4：必须转管理才涨薪 <a class="header-anchor" href="#迷思-4-必须转管理才涨薪" aria-label="Permalink to &quot;迷思 4：必须转管理才涨薪&quot;">​</a></h2><p>反论强调 <strong>IC 双轨</strong> 在大厂与小团队可行，关键是影响面与成果叙事，而非头衔。</p><h2 id="迷思-5-公开写作「掉价」" tabindex="-1">迷思 5：公开写作「掉价」 <a class="header-anchor" href="#迷思-5-公开写作「掉价」" aria-label="Permalink to &quot;迷思 5：公开写作「掉价」&quot;">​</a></h2><p>越来越多资深工程师用博客/X 建立声誉。风险在于浅尝辄止；收益在于招聘与机会主动找上门。</p><h2 id="自省三问-整理者建议" tabindex="-1">自省三问（整理者建议） <a class="header-anchor" href="#自省三问-整理者建议" aria-label="Permalink to &quot;自省三问（整理者建议）&quot;">​</a></h2><ol><li>过去一年我解决了什么<strong>别人解决不了</strong>的问题？</li><li>我的技术栈是变宽还是变深？</li><li>我是否能把复杂决策讲成 5 分钟故事？</li></ol><hr><p>X 上的职业帖情绪化严重，收藏时请隔周重读，比当场点赞更有用。</p>',18)])])}const b=t(n,[["render",l]]);export{u as __pageData,b as default};
